    readonly ObservableCollection<string> files = []; readonly VaultEngine vault = new(); ListBox? fileList; CancellationTokenSource? job; bool busy; string active = "home", output = ""; DateTime activity = DateTime.UtcNow; readonly DispatcherTimer lockTimer = new() { Interval = TimeSpan.FromSeconds(15) };
    public MainWindow() { InitializeComponent(); if (GlobalFontSettings.FontResolver is null) GlobalFontSettings.FontResolver = new SystemFontResolver(); ShowHome(); PreviewMouseDown += (_, _) => activity = DateTime.UtcNow; PreviewKeyDown += (_, _) => activity = DateTime.UtcNow; StateChanged += (_, _) => { if (WindowState == WindowState.Minimized && vault.IsOpen && !busy) { LockVault(); if (active == "vault") ShowVault(); } }; Microsoft.Win32.SystemEvents.SessionSwitch += (_, e) => { if (e.Reason == Microsoft.Win32.SessionSwitchReason.SessionLock) Dispatcher.Invoke(() => { if (!busy) { LockVault(); if (active == "vault") ShowVault(); } }); }; lockTimer.Tick += (_, _) => { if (!busy && vault.IsOpen && DateTime.UtcNow - activity > TimeSpan.FromMinutes(5)) { LockVault(); if (active == "vault") ShowVault(); Status.Text = "Coffre verrouillé après 5 minutes d’inactivité."; } }; lockTimer.Start(); Closing += OnClosing; Loaded += async (_, _) => { if (UpdateEngine.Settings.AutoUpdate) await CheckUpdates(true); }; }
    void OnClosing(object? sender, CancelEventArgs e) { if (busy) { e.Cancel = true; MessageBox.Show("Un traitement est en cours. Annulez-le ou attendez sa fin avant de fermer.", "CrémaTools"); return; } LockVault(); try { UpdateEngine.InstallPending(); } catch (Exception error) { Status.Text = error.Message; } }
    void Reset(string name, string title, string subtitle) { if (busy) throw new Exception("Un traitement est en cours. Attendez sa fin ou annulez-le."); if (active == "vault" && name != "vault") LockVault(); active = name; Page.Children.Clear(); Page.Children.Add(Text(title, 30, true)); Page.Children.Add(Text(subtitle, 14, false, "#607087", new Thickness(0, 8, 0, 24))); fileList = null; }
    static TextBlock Text(string value, double size = 14, bool bold = false, string color = "#0D1B2A", Thickness? margin = null) => new() { Text = value, FontSize = size, FontWeight = bold ? FontWeights.SemiBold : FontWeights.Normal, Foreground = (Brush)new BrushConverter().ConvertFromString(color)!, Margin = margin ?? new Thickness(0, 0, 0, 8), TextWrapping = TextWrapping.Wrap };
    Button Button(string title, Action action, bool primary = false) { var b = new Button { Content = title }; if (primary) b.Style = (Style)FindResource("Primary"); b.Click += (_, _) => Safe(action); return b; }
    Button AsyncButton(string title, Func<Task> action, bool primary = false) { var b = new Button { Content = title }; if (primary) b.Style = (Style)FindResource("Primary"); b.Click += async (_, _) => { try { if (busy) throw new Exception("Un traitement est en cours."); await action(); } catch (Exception e) { Error(e); } }; return b; }
    void Safe(Action action) { try { if (busy) throw new Exception("Un traitement est en cours. Attendez sa fin ou annulez-le."); action(); } catch (Exception e) { Error(e); } }
    void Error(Exception e) { Status.Text = e.Message; MessageBox.Show(e.Message, "CrémaTools", MessageBoxButton.OK, MessageBoxImage.Information); }
    static WrapPanel Row(params UIElement[] elements) { var panel = new WrapPanel(); foreach (var el in elements) panel.Children.Add(el); return panel; }
    static ComboBox Combo(IEnumerable<string> options, int selected = 0) { var combo = new ComboBox { ItemsSource = options.ToList(), SelectedIndex = selected, MinWidth = 220 }; return combo; }
    void Info(string title, string body) => MessageBox.Show(body, title, MessageBoxButton.OK, MessageBoxImage.Information);
    void AddFilePicker(string explanation) { Page.Children.Add(Text(explanation, 13, false, "#607087")); Page.Children.Add(Row(Button("＋ Ajouter des fichiers", () => ChooseFiles()), Button("Ajouter un dossier", () => { var dialog = new OpenFolderDialog { Title = "Choisir un dossier de fichiers" }; if (dialog.ShowDialog() == true) AddFiles(Directory.GetFiles(dialog.FolderName)); }), Button("Retirer la sélection", () => { if (fileList is null) return; foreach (var file in fileList.SelectedItems.Cast<string>().ToList()) files.Remove(file); }), Button("Vider", () => files.Clear()))); fileList = new ListBox { ItemsSource = files, Height = 155, SelectionMode = SelectionMode.Extended, Background = Brushes.White, BorderBrush = new SolidColorBrush(Color.FromRgb(220, 229, 240)), Padding = new Thickness(8), Margin = new Thickness(0, 4, 0, 18) }; var dropBox = new Grid(); dropBox.Children.Add(fileList); var hint = Text("Glissez vos fichiers ici\nou cliquez sur Ajouter des fichiers", 16, false, "#8595AA"); hint.HorizontalAlignment = HorizontalAlignment.Center; hint.VerticalAlignment = VerticalAlignment.Center; hint.TextAlignment = TextAlignment.Center; hint.IsHitTestVisible = false; hint.SetBinding(VisibilityProperty, new Binding("Count") { Source = files, Converter = new EmptyVisibilityConverter() }); dropBox.Children.Add(hint); Page.Children.Add(dropBox); }
    void ChooseFiles() { var dialog = new OpenFileDialog { Title = "Ajouter un ou plusieurs fichiers", Multiselect = true, Filter = "Fichiers courants|*.pdf;*.jpg;*.jpeg;*.png;*.webp;*.heic;*.heif;*.avif;*.tif;*.tiff;*.bmp;*.gif;*.docx;*.txt;*.xlsx;*.csv|Tous les fichiers|*.*" }; if (dialog.ShowDialog() == true) AddFiles(dialog.FileNames); }
    void AddFiles(IEnumerable<string> added) { foreach (var file in added.Where(File.Exists)) if (!files.Contains(Path.GetFullPath(file))) files.Add(Path.GetFullPath(file)); Status.Text = files.Count + " fichier(s) dans la sélection."; }
    void OnDrop(object sender, DragEventArgs e) { Safe(() => { if (busy) return; if (active == "vault") { Info("Coffre", "Déverrouillez le coffre puis utilisez Ajouter des documents. Les fichiers ne seront chiffrés qu’après cette action."); return; } if (e.Data.GetData(DataFormats.FileDrop) is string[] dropped) { if (active == "home") ShowConvert(); AddFiles(dropped.SelectMany(f => Directory.Exists(f) ? Directory.GetFiles(f) : [f])); } }); }
    void OutputPicker() { var label = Text(string.IsNullOrEmpty(output) ? "Choisissez où enregistrer les résultats." : output, 12, false, "#607087"); Page.Children.Add(Row(Button("Choisir le dossier de sortie", () => { var dialog = new OpenFolderDialog { Title = "Où enregistrer les résultats ?" }; if (dialog.ShowDialog() == true) { output = dialog.FolderName; label.Text = output; } }), Button("Ouvrir le dossier", () => { if (!Directory.Exists(output)) throw new Exception("Choisissez d’abord un dossier de sortie."); Process.Start(new ProcessStartInfo(output) { UseShellExecute = true }); }))); Page.Children.Add(label); }
    void ValidateJob() { if (files.Count == 0) throw new Exception("Ajoutez un ou plusieurs fichiers."); if (string.IsNullOrEmpty(output)) throw new Exception("Choisissez le dossier de sortie."); }
    async Task RunJob(Func<List<string>, string, IProgress<string>, CancellationToken, Task<JobResult>> action) { if (busy) return; ValidateJob(); busy = true; job = new(); Progress.Visibility = CancelButton.Visibility = Visibility.Visible; var snapshot = files.ToList(); try { var result = await action(snapshot, output, new Progress<string>(s => Status.Text = s), job.Token); Status.Text = $"Terminé : {result.Files.Count} résultat(s), {result.Errors.Count} erreur(s)."; var summary = $"{result.Files.Count} fichier(s) créé(s).\n\nAvant : {Storage.Size(result.Before)}\nAprès : {Storage.Size(result.After)}\n\nLes originaux sont conservés.\nDossier : {output}"; if (result.Errors.Count > 0) summary += "\n\nCertains fichiers n’ont pas été traités :\n" + string.Join("\n", result.Errors.Take(12)); Info("Traitement terminé", summary); } catch (OperationCanceledException) { Status.Text = "Traitement annulé. Les résultats déjà créés restent dans le dossier de sortie."; } finally { busy = false; job.Dispose(); job = null; Progress.Visibility = CancelButton.Visibility = Visibility.Collapsed; } }
    void ShowHome() { Reset("home", "Vos fichiers. Tout simplement.", "Cinq outils utiles, un seul endroit. Choisissez une tuile pour commencer."); var grid = new Grid(); grid.ColumnDefinitions.Add(new()); grid.ColumnDefinitions.Add(new()); for (int i = 0; i < 3; i++) grid.RowDefinitions.Add(new() { Height = GridLength.Auto }); var entries = new[] { ("↘", "Compresser", "Des fichiers plus légers. Des envois plus faciles.", "Réduire le poids des images ou des PDF ; réunir des fichiers dans une archive ZIP ou 7z. Une archive ne rend pas forcément une photo déjà compressée plus petite.", (Action)ShowCompress), ("⇄", "Convertir", "Le bon format, en quelques clics.", "Images vers PDF, PDF vers images, JPEG, PNG, WebP, HEIC, TIFF, BMP et AVIF. Les documents Word ne sont pas convertis par ce module.", (Action)ShowConvert), ("≡", "Renommer et classer", "Un lot de fichiers, des noms bien rangés.", "Préparez des noms avec un compteur, un nom de base et une date. Vérifiez l’aperçu avant d’appliquer. Annulez la dernière opération.", (Action)ShowRename), ("▣", "Scanner et lire le texte", "De la photo au document utile.", "Améliorez les photos, reconnaissez leur texte, exportez en Word modifiable, texte ou PDF recherchable. La reconnaissance peut comporter des erreurs : relisez les résultats.", (Action)ShowScanner), ("▤", "Mon coffre", "Vos documents importants, à l’abri.", "Coffre chiffré local avec phrase secrète, clé de récupération et sauvegarde chiffrée. Pas de synchronisation cloud dans cette première version.", (Action)ShowVault) }; int n = 0; foreach (var entry in entries) { var inside = new StackPanel(); inside.Children.Add(Text(entry.Item1, 28, true, "#2563EB", new Thickness(0, 0, 0, 2))); inside.Children.Add(Text(entry.Item2, 20, true, "#0D1B2A", new Thickness(0, 0, 0, 4))); inside.Children.Add(Text(entry.Item3, 13, false, "#607087")); var buttons = Row(Button("Ouvrir →", entry.Item5, true), Button("ⓘ", () => Info(entry.Item2, entry.Item4))); foreach (Button button in buttons.Children) { button.Padding = new Thickness(12, 7, 12, 7); button.Margin = new Thickness(0, 0, 8, 0); } inside.Children.Add(buttons); var card = new Border { Background = Brushes.White, BorderBrush = new SolidColorBrush(Color.FromRgb(220, 230, 242)), BorderThickness = new Thickness(1), CornerRadius = new CornerRadius(18), Padding = new Thickness(18), Margin = new Thickness(0, 0, 16, 14), Child = inside }; Grid.SetRow(card, n / 2); Grid.SetColumn(card, n % 2); grid.Children.Add(card); n++; } Page.Children.Add(grid); Page.Children.Add(Text("LOCAL PAR DÉFAUT · SANS ABONNEMENT · ORIGINAUX CONSERVÉS", 11, true, "#7890AA", new Thickness(0, 10, 0, 0))); }
