    void ShowCompress() { Reset("compress", "Des fichiers plus légers", "Réduisez le poids pour envoyer facilement, ou réunissez vos documents dans une archive."); AddFilePicker("Images et PDF pour réduire le poids ; tous les types de fichiers pour ZIP et 7z."); var mode = Combo(["Images — Mail (1600 px)", "Images — Bonne qualité (2560 px)", "PDF — Optimisation sans perte", "PDF — Réduire fortement (pages en images)", "Archive ZIP", "Archive 7z"]); Page.Children.Add(Text("Comment voulez-vous compresser ?", 15, true)); Page.Children.Add(mode); var notice = Text("Les images sont converties en JPEG, redimensionnées et débarrassées de leurs métadonnées. Les originaux sont conservés.", 13, false, "#607087"); Page.Children.Add(notice); mode.SelectionChanged += (_, _) => notice.Text = ((string)mode.SelectedItem).StartsWith("PDF") ? ((string)mode.SelectedItem).Contains("fortement") ? "Ce mode transforme les pages en images : texte sélectionnable, formulaires et signatures numériques ne sont pas conservés dans la copie. Choisissez sans perte pour préserver le contenu." : "Le gain dépend du PDF. Si la copie optimisée est plus lourde, le contenu d’origine est conservé dans la copie." : ((string)mode.SelectedItem).StartsWith("Archive") ? "Une archive regroupe les fichiers. ZIP est le plus universel ; 7z peut compresser davantage. Création de RAR non proposée." : "Les images sont converties en JPEG. Les originaux sont conservés."; var zip = new CheckBox { Content = "Regrouper aussi les fichiers réduits dans un ZIP" }; Page.Children.Add(zip); OutputPicker(); Page.Children.Add(AsyncButton("Compresser", () => { string selected = (string)mode.SelectedItem; bool zipped = zip.IsChecked == true; return RunJob((f, o, p, c) => Task.Run(() => FileEngine.Compress(f, o, selected, zipped, p, c))); }, true)); }
    void ShowRename() { Reset("rename", "Renommer et classer", "Un aperçu avant tout changement. Les extensions sont conservées et aucun fichier n’est écrasé."); AddFilePicker("Ajoutez vos photos et fichiers. Le compteur suit l’ordre de la liste."); Page.Children.Add(Text("Modèle du nom : {n} = compteur · {nom} = nom actuel · {date} = date du fichier", 13)); var pattern = new TextBox { Text = "France {n}" }; var start = new TextBox { Text = "1", Width = 90 }; var digits = Combo(["1 chiffre", "2 chiffres — 01", "3 chiffres — 001", "4 chiffres — 0001"]); var classify = Combo(["Ne pas classer", "Par type de fichier", "Par année"]); Page.Children.Add(pattern); Page.Children.Add(Row(Text("Commencer à", 13), start, digits, classify)); var destination = Text("Par défaut : même dossier que chaque fichier.", 12, false, "#607087"); string target = ""; Page.Children.Add(Row(Button("Choisir un dossier de classement", () => { var d = new OpenFolderDialog(); if (d.ShowDialog() == true) { target = d.FolderName; destination.Text = target; } }), Button("Trier par nom", () => { var sorted = files.OrderBy(Path.GetFileName, StringComparer.CurrentCultureIgnoreCase).ToList(); files.Clear(); foreach (var file in sorted) files.Add(file); }), Button("Trier par date", () => { var sorted = files.OrderBy(File.GetLastWriteTime).ToList(); files.Clear(); foreach (var file in sorted) files.Add(file); }))); Page.Children.Add(destination); var table = new DataGrid { Height = 180 }; table.Columns.Add(new DataGridTextColumn { Header = "Nom actuel", Binding = new Binding("Ancien"), Width = new DataGridLength(1, DataGridLengthUnitType.Star) }); table.Columns.Add(new DataGridTextColumn { Header = "Nouveau nom", Binding = new Binding("Nouveau"), Width = new DataGridLength(1, DataGridLengthUnitType.Star) }); table.Columns.Add(new DataGridTextColumn { Header = "Dossier", Binding = new Binding("Dossier"), Width = new DataGridLength(1, DataGridLengthUnitType.Star) }); List<RenameRow>? planned = null; string journal = Storage.FilePath("rename-journal.json"); void Invalidate() { planned = null; table.ItemsSource = null; } pattern.TextChanged += (_, _) => Invalidate(); start.TextChanged += (_, _) => Invalidate(); digits.SelectionChanged += (_, _) => Invalidate(); classify.SelectionChanged += (_, _) => Invalidate(); files.CollectionChanged += (_, _) => Invalidate(); Page.Children.Add(Row(Button("Voir l’aperçu", () => { if (!int.TryParse(start.Text, out int from) || from < 0) throw new Exception("Le compteur doit être un nombre positif."); planned = RenameEngine.Plan(files, pattern.Text, from, digits.SelectedIndex + 1, target, (string)classify.SelectedItem); RenameEngine.Validate(planned); table.ItemsSource = planned; }), AsyncButton("Appliquer ces noms", async () => { if (planned is null) throw new Exception("Vérifiez d’abord l’aperçu."); if (MessageBox.Show($"Renommer ou déplacer {planned.Count} fichier(s) selon l’aperçu ?", "Appliquer", MessageBoxButton.YesNo) != MessageBoxResult.Yes) return; busy = true; try { var copy = planned.ToList(); await Task.Run(() => RenameEngine.Apply(copy, journal)); files.Clear(); foreach (var row in copy) files.Add(row.Destination); Status.Text = "Classement terminé. Vous pouvez annuler la dernière opération."; } finally { busy = false; } }, true), AsyncButton("Annuler le dernier classement", async () => { if (!File.Exists(journal)) throw new Exception("Aucune opération à annuler."); busy = true; try { await Task.Run(() => RenameEngine.Recover(journal)); files.Clear(); table.ItemsSource = null; Status.Text = "Les noms d’origine ont été restaurés."; } finally { busy = false; } }))); Page.Children.Add(table); }
    void ShowScanner() { Reset("scanner", "Scanner et reconnaître le texte", "Une photo, plusieurs pages ou un gros PDF : ajoutez vos fichiers, puis choisissez le résultat."); AddFilePicker("Images et PDF. Les pages sont traitées une par une pour limiter la mémoire utilisée."); var languages = ScannerEngine.Languages(); if (languages.Count == 0) { Page.Children.Add(Text("Aucune langue OCR n’est installée. Ajoutez le français dans Paramètres Windows → Heure et langue → Langue, puis relancez CrémaTools.", 14, true, "#AD5D14")); Page.Children.Add(Button("Ouvrir les langues Windows", () => Process.Start(new ProcessStartInfo("ms-settings:regionlanguage") { UseShellExecute = true }))); return; } var language = Combo(languages, Math.Max(0, languages.FindIndex(l => l.StartsWith("fr")))); var target = Combo(["PDF recherchable", "Word modifiable (.docx)", "Texte (.txt)"]); Page.Children.Add(Text("Langue du document", 14, true)); Page.Children.Add(language); Page.Children.Add(Text("Résultat souhaité", 14, true)); Page.Children.Add(target); var enhance = new CheckBox { Content = "Améliorer la lisibilité : gris, contraste et redressement", IsChecked = true }; Page.Children.Add(enhance); Page.Children.Add(Text("Le Word contient le texte reconnu, sans reproduction exacte de la mise en page. Relisez les noms, dates et montants.", 12, false, "#607087")); OutputPicker(); Page.Children.Add(AsyncButton("Reconnaître le texte", () => { string format = (string)target.SelectedItem, lang = (string)language.SelectedItem; bool improve = enhance.IsChecked == true; return RunJob((f, o, p, c) => Task.Run(() => ScannerEngine.Scan(f, o, format, lang, improve, p, c))); }, true)); }
